"""Prepare fixed-layout, reference-specific pose-sheet prompts. Does not submit jobs."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
D=ROOT/'art/animation-rework'
plan=json.loads((D/'plan.json').read_text())
briefs={b['coreid']:b for b in json.loads((ROOT/'art/pose-atlases/character-briefs.json').read_text())}
roster=json.loads((D/'roster.json').read_text())
common='''Create a production sprite-sheet IMAGE for a side-view pixel-art fighting game. Exactly FOUR columns and FOUR rows, exactly SIXTEEN separate complete-character animation cels in a regular 4x4 grid. Read the poses left-to-right then top-to-bottom. No text, numbering, labels, borders or dividing lines. Pure flat vivid magenta #FF00FF background, including every gap; no ground shadow, scenery, gradient or checkerboard. Crisp deliberate pixel clusters, dark clean outlines, restrained highlights, no blur or antialiasing. Same character identity, head size, limb lengths, clothing and camera scale in every cell. Strict right-facing 3/4 fighting view, both eyes visible where anatomically appropriate. Exactly two arms and two legs, all attached, no baked resting arm beneath a moved arm, no duplicate hands. Keep every full silhouette inside its own 256x256 cell with 18 pixels of empty margin. Use the same ground line at y=230 within each cell. Standing head-to-foot height about 168 pixels; keep that anatomical scale for crouches and lying poses rather than enlarging them to fill the cell. Never crop ears, spikes, hands or feet. Preserve gaps between legs. No travelling projectiles, beams, particles, trails, detached props, partner or extra characters: draw BODY performance and established attire only; the game draws effects separately. The supplied original image is the authority for face and identity. Complete its unseen lower body consistently as described. The poses are successive purposeful key drawings, not recolored duplicates.'''
requests=[]
for number,row in enumerate(roster):
 id=row['runtime_id'];p=plan['fighters'][id];b=briefs[id]
 sheet_a=f'''\nFIGHTER: {row['display_name']}. {b['identity']}\nSheet A contains these exact 16 cels.\nROW1: Intro, four consecutive full-body poses: (1) relaxed guard; (2) first half of this signature introduction: {p['intro']}; (3) second half of that gesture; (4) settle into the same right-facing fighting guard.\nROW2: Signature special, first four poses: (5) body compresses and gathers strength; (6) full anticipation; (7) first clear contact silhouette; (8) controlled retraction. Performance: {p['special']} Draw the character only, no effects or actual projectile.\nROW3: Same signature special, last four poses: (9) second different contact silhouette using the other shoulder/arm; (10) retraction/coil before finishing; (11) strongest final contact with coherent hips/knees/ankles; (12) balanced planted recovery. These poses are used at actual combat contact times; do not invent extra limbs or multiple bodies to imply speed.\nROW4: Ranged cast, four consecutive poses: (13) prepare; (14) maximum anticipation; (15) release; (16) follow-through returning to guard. Performance: {p['cast']} The mouth/hands show release, but DO NOT draw the travelling spit/projectile. Mouth stays attached to face and both arms remain distinct.\nEvery cell must preserve the original identity exactly. No generic replacement mascot.'''
 sheet_b=f'''\nFIGHTER: {row['display_name']}. {b['identity']}\nSheet B contains these exact 16 cels.\nCELLS1–6, reading left-to-right across rows: six consecutive GROUNDED RECOIL drawings: (1) first impact flinch; (2) shoulders push backward; (3) largest recoil with bent knees; (4) feet catch body weight; (5) chest returns; (6) settle to right-facing guard. Performance: {p['recoil']} Face, neck and torso remain connected; feet land at the same ground line.\nCELLS7–16: ten consecutive DEFEAT drawings for this character. Signature emotion/action: {p['defeat']} No loose props; express the action with body and existing attire only.\n(7) exhausted standing stagger; (8) knees buckle; (9) controlled collapse onto a forearm/hip; (10) body contacts floor; (11) fully grounded side-rest with head visible; (12) slight effort to raise head/shoulder while staying grounded; (13) effort fails and shoulder settles; (14) relaxed side-rest, feet and arms coherent; (15) small final settling; (16) still defeated resting pose, eyes closed or tired, both limbs accounted for.\nCritical: CELLS11–16 are ALL on the floor and NEVER return to sitting or standing. They form a coherent short loop-free settling animation after an airborne KO already lands. Keep standing anatomical scale unchanged even though lying poses have smaller height and more width. No gore, self-harm imagery or dismemberment. Body supported by hip/side and forearm, not balanced on skull. Keep full silhouette within cell.\nNo rotation of one copied standing figure: draw bent joints and weight on the floor convincingly. Exactly 16 cels, no blank or duplicate extra cells.'''
 for sheet,extra in [('a',sheet_a),('b',sheet_b)]:
  prompt=common+extra
  index=number*2+(sheet=='b')
  req={'index':index,'fighter':id,'name':row['display_name'],'sheet':sheet,'reference':row['local_reference'],'library_file_id':row['library_file_id'],'params':{'model':'flux_2','variant':'pro','resolution':'1k','aspect_ratio':'1:1','count':1,'use_unlim':False,'prompt':prompt}}
  requests.append(req)
(D/'requests.json').write_text(json.dumps(requests,indent=2)+'\n')
plan['status']='48 existing credits approved; pilot pending'
plan['approved_budget_credits']=48
plan['billing']='User authorized up to48 existing credits, no purchase/subscription change. Use FLUX.2 Pro1k at quoted1credit/image. WebsiteUnlimited fallback requested, but official policy excludes automation; do not evade a rejected allowance.'
(D/'plan.json').write_text(json.dumps(plan,indent=2)+'\n')
print('Prepared42 reference-specific requests; no generation submitted.')
